INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 130011, "2024/10/31 12:00:00", 2.1, 0.0, 1, 3001100, "2030/01/01 14:59:59", 2, "ヤマト", 100, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 3001);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 130011, "2024/10/31 12:00:00", 5.68, 0.0, 4, 3001101, "2030/01/01 14:59:59", 2, "ヤマト", 101, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 3001);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 130011, "2024/10/31 12:00:00", 0.0, 0.0, 1, 3001102, "2030/01/01 14:59:59", 1, "ヤマト", 102, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 3001);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 130211, "2024/10/31 12:00:00", 0.0, 0.0, 1, 3002100, "2030/01/01 14:59:59", 1, "フブキ", 100, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 130211, "2024/10/31 12:00:00", 0.0, 0.0, 1, 3002101, "2030/01/01 14:59:59", 1, "フブキ", 101, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 130211, "2024/10/31 12:00:00", 8.53, 0.0, 5, 3002102, "2030/01/01 14:59:59", 2, "フブキ", 102, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 130211, "2024/10/31 12:00:00", 5.67, 0.0, 7, 3002103, "2030/01/01 14:59:59", 1, "フブキ", 103, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 130211, "2024/10/31 12:00:00", 0.0, 0.0, 1, 3002104, "2030/01/01 14:59:59", 1, "フブキ", 104, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 3002);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 130211, "2024/10/31 12:00:00", 0.0, 0.0, 3, 3002300, "2030/01/01 14:59:59", 3, "フブキ", 300, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 3004);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 130211, "2024/10/31 12:00:00", 0.0, 0.0, 7, 3002400, "2030/01/01 14:59:59", 7, "フブキ", 301, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 3005);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 130211, "2024/10/31 12:00:00", 4.4, 0.0, 2, 3003200, "2030/01/01 14:59:59", 1, "フブキ", 200, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 3003);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 130211, "2024/10/31 12:00:00", 0.0, 0.0, 7, 3003201, "2030/01/01 14:59:59", 7, "フブキ", 201, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 3003);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (-416.5, 130211, "2024/10/31 12:00:00", 5.6, 0.0, 1, 3003202, "2030/01/01 14:59:59", 2, "フブキ", 202, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 3003);
